import type { StudyDay } from "@/types";
import { StudyPlanCard } from "./StudyPlanCard";

export function Timeline({
  days,
}: {
  days: StudyDay[];
}) {
  return (
    <div className="grid-plan">
      {days.map((day) => (
        <StudyPlanCard
          key={day.day}
          day={day}
        />
      ))}
    </div>
  );
}